DE_REST_A1 = {
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_0'): 'Er ist sicher in diese Höhle eingedrungen.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_1'): 'Was soll das bedeuten?!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_10'): 'Wirst du es bestrafen?\nIch habe dich damals gewarnt, glaube ich.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_11'): 'Und doch fiel mein Rat auf taube Ohren.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_12'): 'Aber... Aber, Tama...!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_13'): 'Dieser Dämon trägt frische Wunden.\nVielleicht wurde er von seinen Kameraden verstoßen?',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_14'): 'Auch wenn er Teil des Plans war,\nvielleicht hat seine Vertrautheit mit Menschen\nden anderen Dämonen Misstrauen eingejagt.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_15'): '...',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_16'): 'Merke dir: Das ändert nichts an der Tatsache,\ndass Dämonen im Herzen immer böse sind.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_17'): 'Aber, Prinzessin, würdest du nicht zugeben,\ndass er bereits angemessen bestraft wurde?',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_18'): 'Ich weiß... Ich weiß das, Tama.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_19'): 'Ich weiß, dass es nicht aus eigenem Willen\nzum Pass gekommen ist.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_2'): 'Sah-Sah!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_20'): 'Ich weiß, dass es nur von Ishimaru benutzt wurde.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_21'): 'Meine Güte... Wenn es nur angegriffen hätte,\nkönnte ich Haseneintopf daraus gemacht haben,\nohne einen zweiten Gedanken zu verlieren.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_22'): 'Sorge nicht. Ich werde meine Hand zurückhalten.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_23'): 'Derweil kannst du das hier essen.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_24'): 'Ich werde deine Verfehlungen nie vergessen.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_25'): 'Wenn jedoch die Last des Vorwurfs, den du trägst,\nzu viel ist, um sie allein zu schultern...',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_26'): '...können wir dich wenigstens von unserem Teil entlasten.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_27'): 'Wir werden die Schuld nicht länger auf dich schieben.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_28'): 'Wir vergeben dir. Also... leb noch ein bisschen länger.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_29'): 'Lass uns gehen, Kaimaru.',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_3'): 'Sieh mal her, Kaimaru! Hast du vergessen,\nwas das Ding mit uns gemacht hat?',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_4'): 'Warum bist du eigentlich...?!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_5'): 'Eine Entschuldigung ist keine angemessene Wiedergutmachung!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_6'): 'Wir haben unser Haus, unsere Lebensgrundlage verloren...\nAlles nur, weil du das getan hast!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_7'): 'Wir hätten sterben können!\nEs wäre nur deshalb so ausgegangen, weil...',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_8'): 'Prinzessin!',
    ('Text/Event/Event/CaveUsagi.csvtxt', 'English#c:07000102_9'): 'Was beabsichtigt du dann zu tun?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_0'): 'Es ist eine Ewigkeit her, dass ich\nzuletzt nach Hause kam. Endlich kann ich mich entspannen.',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_1'): 'Nach dem Verhalten Lady Kamuhitsukis\nscheint es, als hätte ich mir ihre\nVerzeihung so mehr oder weniger verdient.',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_10'): 'Die Feldarbeit war so lästig, und nur ich\nkonnte sie bewältigen. Diese Pause ist eine Erleichterung.',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_11'): 'Warte... Habe ich beim Weggehen\ndas Wasserstor offen gelassen? Oder geschlossen?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_12'): 'Habe ich Tauemon Anweisungen gegeben,\nwas zu tun ist, wenn ich fort bin?\nKann ich ihnen zutrauen, den Pass nicht anzuzünden?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_13'): 'Schaffen sie es mehrere Tage ohne mich?\nWenn plötzlich ein Sturm aufzieht,\nwo würden sie Schutz suchen?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_14'): 'Urrrgh, so viel zur Pause.\nIch mache mir so große Sorgen, dass ich nicht schlafen kann.',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_2'): 'Sicher hätte niemand etwas dagegen,\nwenn ich einfach auf die Insel ginge, Reis\nanbaute und dann sofort zurückkäme?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_3'): 'Dein Eifer, dich um jeden Preis zu drücken,\nwar stets dein größtes Laster.',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_4'): 'Aber komm! Habe ich mir nicht wenigstens\nein paar Tage Pause an der Hauptstadt verdient?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_5'): 'Wenn Kokorowa nicht mit mir sprechen will, kaufe ich eben ein,\nlese Oborozuki Koshis neues Werk, frische meinen Kleiderschrank auf...',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_6'): 'Heehee, solch dekadente Freuden warten!\nIch kann mich kaum halten!',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_7'): 'Urgh, so laut... Man würde meinen, ein\nSchwert könne nicht so einen\nKrach beim Schlafen machen...',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_8'): 'Hm... Ich frage mich, was sie alle\ngerade wohl tun?',
    ('Text/Event/Miyako/SakunaRoom.csvtxt', 'English#c:04010502_9'): 'Ashigumo wacht über sie,\nalso sollten sie eine Weile\nauch ohne mich zurechtkommen.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_0'): 'Bwaha! Ich kann meinen Zehnt jedes Jahr\nallein mit dem Reis bestreiten, den ich daheim\nhabe. Wie herrlich, ein hochgestellter Adliger zu sein!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_1'): 'I-Ist das so? Ich selbst\nmuss jede Mühe aufwenden.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_10'): 'Wenn du an deinen Platz zurückkehrst, darfst\ndich nicht nochmals dem Trinken hingeben.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_11'): 'Schon wieder? Du bist so lästig, Tama.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_12'): 'Betrunkensein hat nichts mit meiner Fähigkeit\nzu tun, meine Pflicht zu erfüllen. Kinderspiel für... Hä?',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_13'): 'Uh-oh...',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_14'): 'Und wo meinst du hinzugehen?!\nIch bin noch nicht fertig mit--',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_15'): 'Entschuldige, Tama. Ich lag falsch.\nIch werde nüchtern werden und ans Werk gehen.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_16'): 'Ich bin sogleich zurück.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_17'): 'Oh, meine Prinzessin...\nSo hast du endlich gelernt, auf meine Worte zu hören!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_18'): 'Hey, ihr Menschen!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_19'): 'Augh, das ist nicht gut. Das ist NICHT gut.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_2'): 'Ich hoffe, Lady Kamuhitsuki\nwird mich auch dieses Jahr anerkennen.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_20'): 'Meine Pflicht ist mir egal. Ich gerate in große\nSchwierigkeiten, wenn die Menschenkinder hier\nhereinkommen! Ich muss sie fangen, und zwar schnell!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_3'): 'Schade, schade!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_4'): 'Du kannst den Rang nicht wechseln,\nin den du geboren wurdest!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_5'): 'Ah, ich weiß! Meine teure Freundin Kokorowa,\nich verleihe dir die Ehre, mir zu helfen.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_6'): 'Je öfter du vor Lady Kamuhitsuki erscheinst,\ndesto eher wird sie sich an dich erinnern.\nHaha!',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_7'): 'R-Rechtschön. Dann wäre so freundlich...',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_8'): 'Lady Kokorowa...',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000201_9'): 'Meine Prinzessin, bitte unterlasse diesen Scherz.\nDu musst deine eigene wichtige Pflicht erfüllen.',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000305_0'): 'Was war das für ein lautes Geräusch?',
    ('Text/Event/Miyako/Utage.csvtxt', 'English#c:98000305_1'): 'Ich rieche etwas... Duftendes.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_0'): 'Wir stecken tatsächlich in großer Not...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_1'): 'Glücklicherweise gibt es in der Nähe Essen und Wasser,\naber wir halten nicht lange durch. Soll ich mich\nwagen, oder Lady Sakuna vertrauen, dass sie uns findet?',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_10'): 'Ah, gut! Ich sehe, dass Kaimaru bei dir ist.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_11'): 'Herrje. Woran hast du gedacht,\nso weit in dieses entlegene Tal zu kommen?\nIch habe überall nach dir gesucht, weißt du!',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_12'): 'Ah, aber... Das ist, also...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_13'): 'Ich schätze, du hast gut daran getan, Kaimaru\nzu finden und ihn all die Zeit zu beschützen.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_14'): 'Du hast mir Zeit gespart, wenn schon nichts anderes.\nDafür gebührt dir ein Lob.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_15'): 'Oh, danke, meine Herrin! Du ehrest mich!',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_16'): 'S-Sicher...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_17'): 'Wie auch immer, meine Schuld ist nun beglichen.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_18'): 'Was? Deine „Schuld"?',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_19'): 'Übrigens ist hier etwas Seltsames.\nEs sieht nicht nach einem Dämon aus, aber...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_2'): 'In jener Nacht vor langer Zeit... blieben wir alle\nin einer Höhle, die dieser ähnlich sah.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_20'): 'Kwah!',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_21'): 'Ich glaube, es ist...ein Kappa.\nEs wirkt freundlich.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_22'): 'Ich würde wetten, Kaimaru ist ihm hierher gefolgt.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_23'): 'Hm. Ich habe so ein Wesen noch nie gesehen.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_24'): 'Du stinkst nach Fisch, Bengel.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_25'): 'Kweh?',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_26'): 'Mmm...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_27'): 'Ah, du bist wach.\nLady Sakuna ist uns zu Hilfe gekommen.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_28'): 'Sah-Sah!',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_29'): 'Ja, ja. „Sah-Sah" ist da, um zu retten.\nNun kehren wir schleunigst nach Hause zurück.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_3'): 'Dein Vater war der Anführer der Banditen,\naber er war ein guter Mensch.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_30'): '...Ich kann mich NICHT erinnern, dich\neingeladen zu haben, Schleimklumpen!',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_4'): 'Er hasste den Krieg von ganzem Herzen,\nund er stahl nie von den Armen.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_5'): 'Kaimaru... Ich bin mir fast sicher, dass du gesehen hast,\nwie dein Vater jener Nacht unter Ishimars Klinge fiel.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_6'): 'Ich weiß nicht, wann du deine Stimme wiedererlangst,\naber...',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_7'): 'Bis dahin beschütze ich dich mit meinem Leben.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_8'): 'So bist du also hier, sogenannter Samurai.',
    ('Text/Event/Sui/CaveKappa.csvtxt', 'English#c:03000203_9'): 'Lady Sakuna!',
}

